typedef struct {
      int elementos[100];
      int topo;
}pilha;
pilha * cria_pilha() {
      pilha * p =malloc(sizeof(pilha));
      p->topo = -1;
      return pilha;
}
void push(pilha *p, int elemento) {
      if (p->topo >= 99)
 return;
      p->elementos[++p->topo] = elemento;
